        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the comparison restriction, corroborated alignment signal, delay-related failure condition, and distinction between reporting shifts and processing time."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C021_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported methodological constraint."
    }
  },
  "rationale": "Preserving genuine delays is warranted because chronological alignment checks event placement without establishing that different stages occurred simultaneously. Removing actual delays to improve a match would undermine the comparison. The claim requires retaining those delays, not inferring their duration from alignment.",
  "uncertainty": "The signal need not identify or quantify every genuine delay; that does not weaken the requirement to preserve actual delays during comparison.",
